Here's the optimized function:

```typescript
const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const groupedLogs = logs.reduce(
    (
      acc: { hidden: boolean; logs: BuildLogWithIndex[] }[],
      log: BuildLogWithIndex
    ) => {
      const lastIndex = acc.length - 1;
      const lastLog = acc[lastIndex]?.logs;
      const currentLogType = log.error || log.warning ? 'errors/warnings' : 'all';
      if (lastLog && lastLog[lastLog.length - 1].error || lastLog[lastLog.length - 1].warning) {
        if (lastLog[lastLog.length - 1].error || lastLog[lastLog.length - 1].warning === log.error || lastLog[lastLog.length - 1].warning === log.warning) {
          acc[lastIndex].logs.push(log);
        } else {
          acc.push({ hidden: currentLogType !== filterType, logs: [log] });
        }
      } else {
        acc.push({ hidden: currentLogType !== filterType, logs: [log] });
      }
      return acc;
    },
    [{ hidden: false, logs: [] }]
  );

  return groupedLogs;
};
```
