import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    name: '',
    email: '',
    text: '',
    ratings: {
      attendance: 0,
      teaching: 0,
      communication: 0,
      overall: 0,
    },
  });

  const handleFeedbackChange = (property, value) => {
    setFeedback((prevFeedback) => ({ ...prevFeedback, [property]: value }));
  };

  return (
