Here is a simple implementation of a pendulum swing simulator using JavaScript and the HTML5 canvas element. This implementation assumes a simple physics model, where the pendulum is experiencing only gravity and air resistance (which is modeled as a simple dampening force).

```javascript
// Pendulum properties
var mass = 0.1; // kg
var length = 200; // cm
var damping = 0.9; // fraction of the pendulum's velocity that is lost each time step
var gravity = 0.0981; // m/s^2 (gravity constant on earth)

// Initial angle
var initialAngle = 30; // degrees

// Pendulum's initial velocity
var initialVelocity = 0;

// Time and time step
var time = 0;
var timeStep = 0.01;

var ctx;
var pendulumX;
var pendulumY;
var velocity;
var acceleration;

function update() {
  // Calculate the force of gravity on the pendulum
  var force = gravity * mass * length * Math.sin(Math.PI / 180 * initialAngle);

  // Calculate the pendulum's acceleration
  acceleration = force / (mass * length);

  // Update the pendulum's velocity
  velocity += acceleration * timeStep;

  // Update the pendulum's angle
  initialAngle += velocity * timeStep;

  // Apply damping
  velocity *= damping;

  // Check for collisions with the floor
  if (initialAngle > 90) {
    initialAngle = 90;
    velocity = -velocity;
  }

  // Clear the canvas
  ctx.clearRect(0, 0, 500, 500);

  // Draw the pendulum
  pendulumX = 250 + Math.sin(Math.PI / 180 * initialAngle) * length;
  pendulumY = 250 - Math.cos(Math.PI / 180 * initialAngle) * length;
  ctx.beginPath();
  ctx.arc(pendulumX, pendulumY, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'blue';
  ctx.fill();

  // Update the time
  time += timeStep;

  // Check for the user's request to stop the pendulum
  if (time % (10 / 60) < timeStep) {
    velocity = 0;
    initialAngle = 0;
  }

  // Request the next frame
  requestAnimationFrame(update);
}

function startPendulum() {
  // Initialize the graphics context
  ctx = document.getElementById('canvas').getContext('2d');

  // Initialize the pendulum's velocity
  initialVelocity = -Math.PI / 180 * initialAngle * Math.sqrt(2 * gravity / length);

  // Start the simulation
  update();
}

// Start the pendulum when the page loads
window.addEventListener('load', function() {
  var pendulumButton = document.getElementById('startPendulumButton');
  pendulumButton.addEventListener('click', function() {
    startPendulum();
  });
});
```

