func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your_region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS Snapshots with the "backup_type" tag
	desc := &ec2.DescribeSnapshotsInput{}
	resp, err := ec2Svc.DescribeSnapshots(desc)
	if err != nil {
		return nil, err
	}

